def test_section_citation_path_summary_gets_source_id_from_top_level_evidence():
    review = normalise_review_json(
        {
            "verdict": "SAFE_WITH_CONDITIONS",
            "evidence_citations": [
                {
                    "source_id": "/tmp/evolution_seed_research_payload.txt",
                    "source_kind": "file",
                    "quote_or_summary": "Seed payload source",
                    "supports": "verdict",
                }
            ],
            "sections": {
                "architecture_boundaries": {
                    "status": "issues_found",
                    "summary": "The section cites the seed payload path but omits structured fields.",
                    "evidence_examined": ["/tmp/evolution_seed_research_payload.txt"],
                    "evidence_citations": [
                        {
                            "quote_or_summary": "/tmp/evolution_seed_research_payload.txt",
                        }
                    ],
                    "findings": [],
                }
            },
        },
        {"oracle": {"model": "gpt-5.5", "reasoning_effort": "high", "backend": "subagent-runner"}},
        _request(),
    )

    citation = review["sections"]["architecture_boundaries"]["evidence_citations"][0]
    assert citation["source_id"] == "/tmp/evolution_seed_research_payload.txt"
    assert citation["source_kind"] == "file"


